(function(){
// ===== DONNÉES =====
const LOGO_B64 = "data:image/png;base64,";
let residents = [];

const BRAND_COLORS = ["#7CB780","#EC663C","#9888C0","#F18A00","#0062AD","#FED100","#7FCDE6","#457556","#A51916","#E0156A","#000000"];
let selectedColor = "#7CB780";
let selectedAlign = "left";

function hexToRgb(hex) {
  const h = hex.replace('#','');
  return [parseInt(h.substring(0,2),16), parseInt(h.substring(2,4),16), parseInt(h.substring(4,6),16)];
}

// ===== FERMETURE MODALES AU CLAVIER =====
document.addEventListener('keydown', e => {
  if(e.key === 'Escape') {
    const rm = document.getElementById('residence-modal');
    if(rm && rm.style.display !== 'none') closeResidenceModal();
    const cm = document.getElementById('confirm-clear-modal');
    if(cm && cm.style.display !== 'none') closeConfirmClear();
  }
});

// ===== CUSTOMIZATION =====
function initCustomization() {
  const sw = document.getElementById('color-swatches');
  if(!sw) return;
  sw.innerHTML = '';
  BRAND_COLORS.forEach(color => {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'color-swatch' + (color.toLowerCase() === selectedColor.toLowerCase() ? ' selected' : '');
    btn.style.background = color;
    btn.title = color;
    btn.setAttribute('aria-label', 'Couleur ' + color);
    btn.setAttribute('aria-pressed', color.toLowerCase() === selectedColor.toLowerCase() ? 'true' : 'false');
    btn.onclick = () => setColor(color);
    sw.appendChild(btn);
  });
}

function setColor(color) {
  selectedColor = color;
  document.querySelectorAll('.color-swatch').forEach(el => {
    const isSel = el.title.toLowerCase() === color.toLowerCase();
    el.classList.toggle('selected', isSel);
    el.setAttribute('aria-pressed', isSel ? 'true' : 'false');
  });
  onOptionsChange();
}

function setAlign(align) {
  selectedAlign = align;
  document.getElementById('align-left').classList.toggle('selected', align === 'left');
  document.getElementById('align-center').classList.toggle('selected', align === 'center');
  onOptionsChange();
}
window.setAlign = setAlign; // export global immédiat (requis par onclick/onchange/oninput)

function getOptions() {
  return {
    showLogo: document.getElementById('opt-logo')?.checked ?? true,
    showBorder: true,
    showDivider: document.getElementById('opt-divider')?.checked ?? true,
    align: selectedAlign,
    color: selectedColor,
    fontSizeAppt: parseFloat(document.getElementById('font-size-appt')?.value) || 9,
    fontSizeNom: parseFloat(document.getElementById('font-size-nom')?.value) || 11
  };
}

function onOptionsChange() {
  renderLabelPreview();
}
window.onOptionsChange = onOptionsChange; // export global immédiat (requis par onclick/onchange/oninput)

function onFontSizeChange() {
  document.getElementById('font-size-appt-val').textContent = document.getElementById('font-size-appt').value + ' pt';
  document.getElementById('font-size-nom-val').textContent = document.getElementById('font-size-nom').value + ' pt';
  onOptionsChange();
}
window.onFontSizeChange = onFontSizeChange; // export global immédiat (requis par onclick/onchange/oninput)

// ===== TEMPLATE DOWNLOAD =====
function downloadTemplate() {
  const wb = XLSX.utils.book_new();
  const ws = XLSX.utils.aoa_to_sheet([
    ['N_LOGEMENT','TYPE','TITRE_1','NOM_1','PRENOM_1','TITRE_2','NOM_2','PRENOM_2'],
    ['B103','Appartement','Mme.','DUPONT','Marie','M.','MARTIN','Pierre'],
    ['C205','Pavillon','M.','GARCIA','Carlos','','',''],
    ['D310','Appartement','-','LAMBERT','Camille','','','']
  ]);
  ws['!cols'] = [{wch:14},{wch:14},{wch:12},{wch:18},{wch:16},{wch:12},{wch:18},{wch:16}];
  XLSX.utils.book_append_sheet(wb, ws, 'Résidents');
  XLSX.writeFile(wb, 'modele-residents.xlsx');
}
window.downloadTemplate = downloadTemplate; // export global immédiat (requis par onclick/onchange/oninput)

// ===== DRAG & DROP =====
const dz = document.getElementById('dropzone');
dz.addEventListener('dragover', e => { e.preventDefault(); dz.classList.add('drag-over'); });
dz.addEventListener('dragleave', () => dz.classList.remove('drag-over'));
dz.addEventListener('drop', e => {
  e.preventDefault();
  dz.classList.remove('drag-over');
  const f = e.dataTransfer.files[0];
  if(f) handleFile(f);
});

// ===== IMPORT FICHIER (XLSX/XLS/CSV) — TOLÉRANT AUX VARIANTES DE COLONNES =====
function pickField(row, keys) {
  for(let i = 0; i < keys.length; i++) {
    const v = row[keys[i]];
    if(v !== undefined && String(v).trim() !== '') return String(v).trim();
  }
  return '';
}

// Ramène toute valeur de titre importée (Madame, M, Mr, Mme, vide, ...) à l'une des 3 valeurs
// gérées par le menu déroulant du tableau : « M. », « Mme. » ou « - » (non genré / pas de titre).
function normalizeTitre(raw) {
  const v = String(raw || '').trim().toLowerCase();
  if(!v || v === '-') return '-';
  if(v.startsWith('mme') || v.startsWith('madame')) return 'Mme.';
  if(v.startsWith('m')) return 'M.'; // couvre m, m., mr, mr., monsieur
  return '-';
}

function handleFile(file) {
  if(!file) return;
  const ext = file.name.split('.').pop().toLowerCase();
  if(!['xlsx','xls','csv'].includes(ext)) {
    showAlert('file-alert', 'error', 'Format non supporté. Utilisez un fichier .xlsx, .xls ou .csv');
    return;
  }
  const reader = new FileReader();
  reader.onload = e => {
    try {
      const wb = XLSX.read(e.target.result, {type:'array'});
      const ws = wb.Sheets[wb.SheetNames[0]];
      const data = XLSX.utils.sheet_to_json(ws, {defval:''});
      if(!data.length) { showAlert('file-alert','error','Le fichier est vide.'); return; }

      const imported = data.map(row => {
        const rawType = pickField(row, ['TYPE','TYPE_LOGEMENT','TYPE LOGEMENT','Type','Type logement']).toLowerCase();
        return {
          appt: pickField(row, ['N_LOGEMENT','N LOGEMENT','NLOGEMENT','LOGEMENT','APT','Logement','N° Logement']),
          type: rawType.startsWith('pav') ? 'pavillon' : 'appt',
          titre1: normalizeTitre(pickField(row, ['TITRE_1','TITRE 1','Titre 1','TITRE1'])),
          titre2: normalizeTitre(pickField(row, ['TITRE_2','TITRE 2','Titre 2','TITRE2'])),
          nom1: pickField(row, ['NOM_1','NOM 1','Nom 1','NOM1','NOM']).toUpperCase(),
          prenom1: pickField(row, ['PRENOM_1','PRENOM 1','Prénom 1','PRÉNOM_1','PRENOM1']),
          nom2: pickField(row, ['NOM_2','NOM 2','Nom 2','NOM2']).toUpperCase(),
          prenom2: pickField(row, ['PRENOM_2','PRENOM 2','Prénom 2','PRÉNOM_2','PRENOM2']),
        };
      }).filter(r => r.appt && r.nom1);

      if(!imported.length) {
        showAlert('file-alert','error','Aucune ligne valide trouvée. Vérifiez les colonnes N_LOGEMENT et NOM_1 (ou équivalents).');
        return;
      }

      residents = residents.concat(imported);
      showAlert('file-alert','success', imported.length + ' résident(s) importé(s) depuis "' + file.name + '"');
      renderPreview();
      renderLabelPreview();
      document.getElementById('dropzone').classList.add('has-file');
      document.getElementById('dropzone-title').textContent = '✓ ' + file.name;
      document.getElementById('btn-generate').disabled = false;
    } catch(err) {
      showAlert('file-alert','error','Erreur de lecture : ' + err.message);
    }
  };
  reader.readAsArrayBuffer(file);
}
window.handleFile = handleFile; // export global immédiat (requis par onclick/onchange/oninput)

function clearFile() {
  residents = [];
  document.getElementById('preview-section').style.display = 'none';
  document.getElementById('empty-state').style.display = 'block';
  document.getElementById('preview-empty-state').style.display = 'block';
  document.getElementById('label-preview-grid').innerHTML = '';
  document.getElementById('count-row').style.display = 'none';
  const manualBtn = document.getElementById('btn-manual-entry');
  if(manualBtn) manualBtn.style.display = 'inline-flex';
  document.getElementById('file-alert').innerHTML = '';
  document.getElementById('btn-generate').disabled = true;
  document.getElementById('dropzone').classList.remove('has-file');
  document.getElementById('dropzone-title').textContent = 'Cliquer ou glisser un fichier';
  document.getElementById('fileInput').value = '';
}
window.clearFile = clearFile; // export global immédiat (requis par onclick/onchange/oninput)

// Demande confirmation avant de tout effacer (dès qu'il y a quelque chose à perdre) :
// un clic malheureux sur « Vider » ne doit pas pouvoir supprimer instantanément
// toute une liste de résidents saisie ou importée, sans possibilité de revenir en arrière.
function requestClearAll() {
  if(!residents.length) { clearFile(); return; }
  document.getElementById('confirm-clear-count').textContent = residents.length;
  document.getElementById('confirm-clear-modal').style.display = 'flex';
}
window.requestClearAll = requestClearAll; // export global immédiat (requis par onclick/onchange/oninput)

function closeConfirmClear() {
  document.getElementById('confirm-clear-modal').style.display = 'none';
}
window.closeConfirmClear = closeConfirmClear; // export global immédiat (requis par onclick/onchange/oninput)

function confirmClearAll() {
  closeConfirmClear();
  clearFile();
}
window.confirmClearAll = confirmClearAll; // export global immédiat (requis par onclick/onchange/oninput)

// ===== SAISIE MANUELLE (DIRECTEMENT DANS LE TABLEAU) =====
// Plus de formulaire séparé : « Saisie manuelle » ajoute directement une ligne vide dans le
// tableau et place le curseur dans sa première case, prête à taper. Une fois qu'il y a au moins
// un résident, ce bouton s'efface au profit de « + Ligne vide » (même action, pas de doublon).
function startManualEntry() {
  addEmptyRow();
}
window.startManualEntry = startManualEntry; // export global immédiat (requis par onclick/onchange/oninput)

function focusNewestRow() {
  requestAnimationFrame(() => {
    const cell = document.querySelector('#preview-body tr:last-child .editable-cell');
    if(!cell) return;
    cell.scrollIntoView({ block: 'nearest', inline: 'nearest' });
    cell.focus();
  });
}

// ===== PREVIEW TABLE ÉDITABLE =====
function renderPreview() {
  document.getElementById('empty-state').style.display = residents.length ? 'none' : 'block';
  document.getElementById('preview-section').style.display = residents.length ? 'block' : 'none';
  document.getElementById('count-row').style.display = residents.length ? 'flex' : 'none';
  // « Saisie manuelle » et « + Ligne vide » font strictement la même chose (ajouter une ligne
  // vide dans le tableau) : on n'en montre qu'un seul à la fois pour ne pas avoir deux boutons
  // redondants sous les yeux. Le premier sert à démarrer depuis une liste vide, le second à
  // enchaîner une fois qu'il y a déjà des résidents.
  const manualBtn = document.getElementById('btn-manual-entry');
  if(manualBtn) manualBtn.style.display = residents.length ? 'none' : 'inline-flex';
  updateCount();
  renderTableBody();
  updateGenerateButtonState();
}

// Le bouton « Générer le PDF » ne doit être actif que s'il existe au moins un résident
// exploitable (n° de logement + NOM 1 renseignés) — recalculé à chaque changement des données,
// que ce soit via import, ajout/suppression de ligne, ou édition directe dans le tableau.
function updateGenerateButtonState() {
  document.getElementById('btn-generate').disabled = !residents.some(r => r.appt && r.nom1);
}

// Options du menu déroulant « Titre » : le tiret « - » signifie explicitement une personne ne
// souhaitant pas être genrée — dans ce cas, aucun titre n'est affiché devant le nom/prénom.
const TITRE_OPTIONS = ['M.', 'Mme.', '-'];
function titreOptionsHtml(selected) {
  const val = TITRE_OPTIONS.includes(selected) ? selected : '-';
  return TITRE_OPTIONS.map(t =>
    '<option value="' + t + '"' + (t === val ? ' selected' : '') + '>' + (t === '-' ? '— (non genré)' : t) + '</option>'
  ).join('');
}

function renderTableBody() {
  const body = document.getElementById('preview-body');
  body.innerHTML = residents.map((r, idx) => {
    const typeCell = '<td><select class="editable-cell" onchange="updateResident(' + idx + ',\'type\',this.value)">' +
      '<option value="appt"' + ((r.type||'appt')==='appt' ? ' selected' : '') + '>Appt.</option>' +
      '<option value="pavillon"' + (r.type==='pavillon' ? ' selected' : '') + '>Pav.</option>' +
      '</select></td>';
    const titreCell = (field) => '<td><select class="editable-cell" onchange="updateResident(' + idx + ',\'' + field + '\',this.value)">' + titreOptionsHtml(r[field]) + '</select></td>';
    const textCell = (field) => '<td><input class="editable-cell" value="' + escHtml(r[field] || '') + '" oninput="updateResident(' + idx + ',\'' + field + '\',this.value)"></td>';
    return '<tr>'
      + '<td><input class="editable-cell" value="' + escHtml(r.appt || '') + '" oninput="updateResident(' + idx + ',\'appt\',this.value)"></td>'
      + typeCell + titreCell('titre1') + textCell('prenom1') + textCell('nom1')
      + titreCell('titre2') + textCell('prenom2') + textCell('nom2')
      + '<td><button class="btn-del-row" onclick="deleteRow(' + idx + ')" aria-label="Supprimer la ligne"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a1 1 0 0 1 1-1h4a1 1 0 0 1 1 1v2"/></svg></button></td>'
      + '</tr>';
  }).join('');
  updateTableScrollCue();
}

// Le tableau défile horizontalement dès que le panneau est trop étroit pour ses 9 colonnes
// (voir min-width en CSS). Sans indice visuel, rien ne signale qu'il y a plus de colonnes
// à voir : on affiche un dégradé sur le bord concerné, et une astuce tant que ce n'est pas
// évident, pour que ça ne passe pas inaperçu.
function updateTableScrollCue() {
  const wrap = document.querySelector('#view-etiquettes .preview-wrap');
  const hint = document.getElementById('table-scroll-hint');
  if(!wrap) return;
  const refresh = () => {
    const scrollable = wrap.scrollWidth > wrap.clientWidth + 2;
    if(hint) hint.style.display = scrollable ? 'block' : 'none';
    wrap.classList.toggle('has-more-right', scrollable && (wrap.scrollWidth - wrap.scrollLeft > wrap.clientWidth + 2));
    wrap.classList.toggle('has-more-left', wrap.scrollLeft > 2);
  };
  refresh();
  if(!wrap.dataset.scrollCueBound) {
    wrap.addEventListener('scroll', refresh);
    window.addEventListener('resize', refresh);
    wrap.dataset.scrollCueBound = '1';
  }
}

function updateResident(idx, field, value) {
  if(!residents[idx]) return;
  residents[idx][field] = (field === 'nom1' || field === 'nom2') ? value.toUpperCase() : value;
  updateCount();
  renderLabelPreview();
  updateGenerateButtonState();
}
window.updateResident = updateResident; // export global immédiat (requis par onclick/onchange/oninput)

function deleteRow(idx) {
  residents.splice(idx, 1);
  renderPreview();
  renderLabelPreview();
}
window.deleteRow = deleteRow; // export global immédiat (requis par onclick/onchange/oninput)

function addEmptyRow() {
  residents.push({appt:'',type:'appt',titre1:'-',titre2:'-',nom1:'',prenom1:'',nom2:'',prenom2:''});
  renderPreview();
  renderLabelPreview();
  focusNewestRow();
}
window.addEmptyRow = addEmptyRow; // export global immédiat (requis par onclick/onchange/oninput)

function updateCount() {
  document.getElementById('count-badge').textContent = residents.length + ' résident' + (residents.length !== 1 ? 's' : '');
}

// ===== APERÇU DES ÉTIQUETTES =====
function renderLabelPreview() {
  const grid = document.getElementById('label-preview-grid');
  const emptyState = document.getElementById('preview-empty-state');
  const opts = getOptions();
  const validRes = residents.filter(r => r.appt && r.nom1);

  if(!validRes.length) {
    grid.innerHTML = '';
    emptyState.style.display = 'block';
    return;
  }
  emptyState.style.display = 'none';

  const apptPx = (opts.fontSizeAppt * 1.333).toFixed(1) + 'px';
  const nomPx = (opts.fontSizeNom * 1.333).toFixed(1) + 'px';
  const personPx = (Math.max(opts.fontSizeAppt, 8) * 1.333).toFixed(1) + 'px';
  grid.innerHTML = '';
  validRes.forEach(r => {
    const label = document.createElement('div');
    label.className = 'label-preview';
    label.style.borderColor = opts.showBorder ? opts.color : 'transparent';
    label.style.borderWidth = opts.showBorder ? '1.5px' : '0';
    label.style.alignItems = opts.align === 'center' ? 'center' : 'flex-start';
    label.style.textAlign = opts.align === 'center' ? 'center' : 'left';

    const logoHtml = opts.showLogo ? ('<img src="' + LOGO_B64 + '" alt="">') : '';
    const typeLabel = r.type === 'pavillon' ? 'Pav.' : 'Appt.';
    const line1 = '<div class="label-appt" style="color:' + opts.color + ';font-size:' + apptPx + ';justify-content:' + (opts.align === 'center' ? 'center' : 'flex-start') + '">' + logoHtml + ' ' + typeLabel + ' <strong>' + escHtml(r.appt) + '</strong></div>';

    const dividerHtml = opts.showDivider ? '<div style="height:1px;width:100%;align-self:stretch;background:' + opts.color + ';opacity:0.45;margin:2px 0;"></div>' : '';

    // Ordre d'affichage : Titre, NOM (en gras), Prénom — ex. « M. CORCELLET Thibaut ».
    // Le titre « - » (non genré) ne s'affiche jamais.
    const titrePrefix = (t) => (t && t !== '-') ? escHtml(t) + ' ' : '';
    const p1 = titrePrefix(r.titre1) + '<strong style="color:' + opts.color + ';font-size:' + nomPx + '">' + escHtml(r.nom1) + '</strong>' + (r.prenom1 ? ' ' + escHtml(r.prenom1) : '');
    const p2 = r.nom2 ? (titrePrefix(r.titre2) + '<strong style="color:' + opts.color + ';font-size:' + nomPx + '">' + escHtml(r.nom2) + '</strong>' + (r.prenom2 ? ' ' + escHtml(r.prenom2) : '')) : '';

    label.innerHTML = line1 + dividerHtml + '<div class="label-person" style="font-size:' + personPx + '">' + p1 + '</div>' + (p2 ? '<div class="label-person" style="font-size:' + personPx + '">' + p2 + '</div>' : '');
    grid.appendChild(label);
  });
}

function escHtml(s) {
  return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}

// ===== ALERT =====
function showAlert(containerId, type, msg) {
  const icons = {
    success: '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="flex-shrink:0;margin-top:2px"><polyline points="20 6 9 17 4 12"/></svg>',
    error: '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="flex-shrink:0;margin-top:2px"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>',
    info: '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="flex-shrink:0;margin-top:2px"><circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/></svg>'
  };
  document.getElementById(containerId).innerHTML = '<div class="alert alert-' + type + '">' + (icons[type] || icons.info) + '<div>' + msg + '</div></div>';
}

// ===== MODAL RÉSIDENCE =====
function openResidenceModal() {
  const validRes = residents.filter(r => r.appt && r.nom1);
  if(!validRes.length) { showAlert('generate-alert','error','Aucun résident valide (appt. + NOM 1 requis).'); return; }
  const input = document.getElementById('residence-modal-input');
  input.value = document.getElementById('programme-name')?.value || '';
  document.getElementById('residence-modal').style.display = 'flex';
  setTimeout(() => input.focus(), 50);
}
window.openResidenceModal = openResidenceModal; // export global immédiat (requis par onclick/onchange/oninput)

function closeResidenceModal() {
  document.getElementById('residence-modal').style.display = 'none';
}
window.closeResidenceModal = closeResidenceModal; // export global immédiat (requis par onclick/onchange/oninput)

function confirmResidenceAndGenerate() {
  const name = document.getElementById('residence-modal-input').value.trim();
  if(!name) { document.getElementById('residence-modal-input').focus(); return; }
  document.getElementById('programme-name').value = name;
  updateProgrammeName();
  closeResidenceModal();
  generate(name);
}
window.confirmResidenceAndGenerate = confirmResidenceAndGenerate; // export global immédiat (requis par onclick/onchange/oninput)

function updateProgrammeName() {
  const name = document.getElementById('programme-name')?.value || 'Non défini';
  document.getElementById('footer-programme').textContent = name || 'Non défini';
}
window.updateProgrammeName = updateProgrammeName; // export global immédiat (requis par onclick/onchange/oninput)

// ===== GÉNÉRATION PDF =====
async function generate(residenceName) {
  const validRes = residents.filter(r => r.appt && r.nom1);
  if(!validRes.length) { showAlert('generate-alert','error','Aucun résident valide (appt. + NOM 1 requis).'); return; }
  const btn = document.getElementById('btn-generate');
  btn.disabled = true;
  btn.innerHTML = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="animation:spin 1s linear infinite"><path d="M21 12a9 9 0 1 1-6.219-8.56"/></svg> Génération...';
  document.getElementById('progress-wrap').style.display = 'block';
  setProgress(10);
  showAlert('generate-alert','info','Préparation du PDF...');

  await new Promise(r => setTimeout(r, 50));

  try {
    await generatePDF(validRes, residenceName);
    setProgress(100);
    showAlert('generate-alert','success','✓ PDF généré ! Imprimez à 100% (taille réelle), jamais « Ajuster ».');
  } catch(err) {
    showAlert('generate-alert','error','Erreur : ' + err.message);
  }

  btn.disabled = false;
  btn.innerHTML = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 2v10m0 0l-3-3m3 3l3-3"/><rect x="3" y="17" width="18" height="4" rx="1"/></svg> Générer le PDF';
}

function setProgress(pct) {
  document.getElementById('progress-bar').style.width = pct + '%';
}

// Ordre d'affichage : Titre, NOM (en gras, couleur de marque), Prénom — ex. « M. CORCELLET Thibaut ».
// Le titre « - » (non genré) ne s'affiche jamais.
function drawPersonLine(doc, titre, prenom, nom, leftX, centerX, y, align, darkColor, brandColor, fontSizeAppt, fontSizeNom) {
  titre = (titre && titre !== '-') ? titre : '';
  const fsSmall = fontSizeAppt || 9;
  const fsNom = fontSizeNom || 11;
  doc.setFontSize(fsSmall); doc.setFont('helvetica', 'bold');
  const titreW = titre ? doc.getTextWidth(titre + ' ') : 0;
  doc.setFontSize(fsNom); doc.setFont('helvetica', 'bold');
  const nomW = nom ? doc.getTextWidth(nom + (prenom ? ' ' : '')) : 0;
  doc.setFontSize(fsSmall); doc.setFont('helvetica', 'normal');
  const prenomW = prenom ? doc.getTextWidth(prenom) : 0;
  const totalW = titreW + nomW + prenomW;

  let cx = align === 'center' ? (centerX - totalW / 2) : leftX;

  if(titre) {
    doc.setFontSize(fsSmall); doc.setFont('helvetica', 'bold'); doc.setTextColor(...darkColor);
    doc.text(titre + ' ', cx, y);
    cx += titreW;
  }
  if(nom) {
    doc.setFontSize(fsNom); doc.setFont('helvetica', 'bold'); doc.setTextColor(...brandColor);
    doc.text(nom + (prenom ? ' ' : ''), cx, y);
    cx += nomW;
  }
  if(prenom) {
    doc.setFontSize(fsSmall); doc.setFont('helvetica', 'normal'); doc.setTextColor(...darkColor);
    doc.text(prenom, cx, y);
  }
}

async function generatePDF(residents, residenceName) {
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });

  const opts = getOptions();
  const logoImg = opts.showLogo ? await loadImage(LOGO_B64) : null;
  const programmeName = residenceName || document.getElementById('programme-name')?.value || 'Programme';

  // Dimensions exactes norme BAL française NF D27-404 : 99mm x 25mm
  const PAGE_W = 210, PAGE_H = 297;
  const LABEL_W = 99;
  const LABEL_H = 25;
  const COLS = 2;
  const GAP_X = 2;

  const MARGIN_X = (PAGE_W - (COLS * LABEL_W + (COLS - 1) * GAP_X)) / 2;
  const HEADER_H = 8;
  const MARGIN_Y = 10 + HEADER_H;
  const FOOTER_Y = PAGE_H - 6;

  const BRAND = hexToRgb(opts.color);
  const GREEN = BRAND;
  const GREEN_DARK = BRAND;
  const DARK = [30, 35, 50];

  function drawHeaderFooter(pageIndex, totalPages) {
    doc.setFontSize(10);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(...GREEN_DARK);
    doc.text('Résidence : ' + programmeName, MARGIN_X, 8);

    doc.setFontSize(7.5);
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(120, 125, 140);
    doc.text(
      "OFFICE64 de l'Habitat — Résidence " + programmeName + ' — Page ' + pageIndex + '/' + totalPages,
      PAGE_W / 2, FOOTER_Y, { align: 'center' }
    );
  }

  let labelIdx = 0;
  let pageNum = 0;
  const availH0 = PAGE_H - MARGIN_Y - (PAGE_H - FOOTER_Y + 4);
  const rowsPerPage0 = Math.floor(availH0 / LABEL_H);
  const totalPages = Math.max(1, Math.ceil(residents.length / (rowsPerPage0 * COLS)));

  while(labelIdx < residents.length) {
    if(pageNum > 0) doc.addPage();
    pageNum++;

    const availH = PAGE_H - MARGIN_Y - (PAGE_H - FOOTER_Y + 4);
    const rowsPerPage = Math.floor(availH / LABEL_H);

    drawHeaderFooter(pageNum, totalPages);

    for(let row = 0; row < rowsPerPage && labelIdx < residents.length; row++) {
      for(let col = 0; col < COLS && labelIdx < residents.length; col++) {
        const x = MARGIN_X + col * (LABEL_W + GAP_X);
        const y = MARGIN_Y + row * LABEL_H;
        const r = residents[labelIdx];

        doc.setFillColor(255, 255, 255);
        doc.rect(x, y, LABEL_W, LABEL_H, 'F');

        if(opts.showBorder) {
          doc.setDrawColor(...GREEN);
          doc.setLineWidth(0.45);
          doc.rect(x, y, LABEL_W, LABEL_H, 'S');
        }

        const centerX = x + LABEL_W / 2;
        const leftX = x + 2.5;
        const textAlign = opts.align === 'center' ? 'center' : 'left';

        let logoW = 0;
        const LOGO_H = 6.5;
        if(opts.showLogo && logoImg) {
          logoW = (logoImg.width / logoImg.height) * LOGO_H;
        }

        doc.setFontSize(opts.fontSizeAppt);
        doc.setFont('helvetica', 'bold');
        doc.setTextColor(...GREEN_DARK);
        const typeLabelPdf = r.type === 'pavillon' ? 'Pav.' : 'Appt.';
        const apptText = typeLabelPdf + ' ' + r.appt;
        const apptTextW = doc.getTextWidth(apptText);

        if(opts.align === 'center') {
          const totalW = logoW + (logoW > 0 ? 2.5 : 0) + apptTextW;
          const startX = centerX - totalW / 2;
          if(opts.showLogo && logoImg) doc.addImage(LOGO_B64, 'PNG', startX, y + 1.2, logoW, LOGO_H);
          doc.text(apptText, startX + (logoW > 0 ? logoW + 2.5 : 0), y + 6);
        } else {
          if(opts.showLogo && logoImg) doc.addImage(LOGO_B64, 'PNG', leftX, y + 1.2, logoW, LOGO_H);
          doc.text(apptText, leftX + (logoW > 0 ? logoW + 2.5 : 0), y + 6);
        }

        if(opts.showDivider) {
          doc.setDrawColor(...GREEN);
          doc.setLineWidth(0.2);
          doc.line(x + 2, y + 9.2, x + LABEL_W - 2, y + 9.2);
        }

        const y1 = y + 15.5;
        drawPersonLine(doc, r.titre1, r.prenom1, r.nom1, leftX, centerX, y1, textAlign, DARK, GREEN_DARK, opts.fontSizeAppt, opts.fontSizeNom);

        if(r.nom2) {
          const y2 = y + 22;
          drawPersonLine(doc, r.titre2, r.prenom2, r.nom2, leftX, centerX, y2, textAlign, DARK, GREEN_DARK, opts.fontSizeAppt, opts.fontSizeNom);
        }

        labelIdx++;
        setProgress(10 + Math.round(labelIdx / residents.length * 85));
        await new Promise(r => setTimeout(r, 0));
      }
    }
  }

  const safeResidenceName = programmeName.replace(/[\\/:*?"<>|]/g,'').trim().replace(/\s+/g,'_') || 'Programme';
  const filename = 'Etiquettes_BAL_' + safeResidenceName + '_' + new Date().toISOString().slice(0,10) + '.pdf';
  doc.save(filename);
}

function loadImage(src) {
  return new Promise((res, rej) => {
    const img = new Image();
    img.onload = () => res(img);
    img.onerror = rej;
    img.src = src;
  });
}

// ===== INIT =====
initCustomization();
updateProgrammeName();

})();
